-- QA only; all fixtures and audit entries roll back.
BEGIN;
DO $$
DECLARE org uuid:='3868f88a-fa36-4467-9b31-653143c6ef7d';
 actor uuid:='119aa014-e89a-4075-9398-efb7db5d2a18';
 operador uuid:='47b6c2b6-c423-43ca-9a04-c5995ee194df';
 rs uuid:='5f1c62c9-2971-4f2f-8068-fac70b332b20';
 ins uuid; reg uuid; reg2 uuid; sid uuid; sid2 uuid; cambio uuid; atid uuid; ex uuid;
 lecturas jsonb; datos jsonb; anterior jsonb; den boolean;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=org AND es_prueba) THEN RAISE EXCEPTION 'Solo QA'; END IF;
 EXECUTE 'SET LOCAL ROLE authenticated';
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 INSERT INTO public.tend_instrumentos(org_id,codigo,tipo,parametro,spec_estado) VALUES(org,'T3C-QA','otro','Presión QA','validada') RETURNING id INTO ins;
 INSERT INTO public.tend_registros(org_id,modulo,nombre,instrumento_id) VALUES(org,'presiones','T3c QA',ins) RETURNING id INTO reg;
 INSERT INTO public.tend_registros(org_id,modulo,nombre,instrumento_id) VALUES(org,'presiones','T3c retirado QA',ins) RETURNING id INTO reg2;
 INSERT INTO public.tend_cambios_filtro(org_id,instrumento_id,fecha,nota) VALUES(org,ins,'2026-10-12','QA') RETURNING id INTO cambio;
 SELECT jsonb_agg(jsonb_build_object('dia',dia,'turno',turno,'valor',10,'hora','08:00','quien','Antefirma QA')) INTO lecturas FROM unnest(ARRAY['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo']) dia CROSS JOIN unnest(ARRAY['Mañana','Media tarde','Tarde']) turno;
 datos:=jsonb_build_object('semana_inicio','2026-10-12','mes','CLIENTE','anio','9999','unidad','Pa','lecturas',lecturas,'source','ia');
 sid:=public.tend_guardar_semana(reg,datos);
 sid2:=public.tend_guardar_semana(reg,datos||jsonb_build_object('semana_inicio','2026-10-19'));
 den:=false; BEGIN PERFORM public.tend_corregir_fecha_semana(sid,'2026-10-26'); EXCEPTION WHEN raise_exception THEN IF SQLERRM='Semana con lecturas previas requiere motivo' THEN den:=true; ELSE RAISE; END IF; END;
 IF NOT den THEN RAISE EXCEPTION 'Fecha sin motivo permitida'; END IF;
 SELECT to_jsonb(s) INTO anterior FROM public.tend_semanas s WHERE id=sid;
 PERFORM public.tend_corregir_fecha_semana(sid,'2026-10-26','Corregir lunes del encabezado');
 IF NOT EXISTS(SELECT 1 FROM public.tend_semanas WHERE id=sid AND semana_inicio='2026-10-26' AND mes='octubre' AND anio='2026') THEN RAISE EXCEPTION 'Fecha no conservó id'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.audit_trail WHERE registro_id=sid::text AND accion='SEMANA_CORREGIDA' AND valor_anterior=anterior AND valor_nuevo->>'motivo'='Corregir lunes del encabezado') THEN RAISE EXCEPTION 'Fecha sin auditoría'; END IF;
 den:=false; BEGIN PERFORM public.tend_corregir_fecha_semana(sid,'2026-10-19','QA colisión'); EXCEPTION WHEN raise_exception THEN IF SQLERRM LIKE 'Ya existe una semana%' THEN den:=true; ELSE RAISE; END IF; END;
 IF NOT den THEN RAISE EXCEPTION 'Colisión permitida'; END IF;
 den:=false; BEGIN PERFORM public.tend_retirar('semana',sid2,''); EXCEPTION WHEN raise_exception THEN IF SQLERRM='Retirar requiere motivo' THEN den:=true; ELSE RAISE; END IF; END;
 IF NOT den THEN RAISE EXCEPTION 'Retiro sin motivo permitido'; END IF;
 PERFORM public.tend_retirar('semana',sid2,'Semana duplicada QA');
 PERFORM public.tend_retirar('registro',reg2,'Registro duplicado QA');
 PERFORM public.tend_retirar('cambio_filtro',cambio,'Cambio incorrecto QA');
 IF NOT EXISTS(SELECT 1 FROM public.tend_semanas WHERE id=sid2 AND NOT activo AND retirado_por=actor AND retirado_motivo='Semana duplicada QA') OR NOT EXISTS(SELECT 1 FROM public.tend_registros WHERE id=reg2 AND NOT activo) OR NOT EXISTS(SELECT 1 FROM public.tend_cambios_filtro WHERE id=cambio AND NOT activo) THEN RAISE EXCEPTION 'Retiro borró o perdió motivo'; END IF;
 IF (SELECT count(*) FROM public.audit_trail WHERE accion='REGISTRO_RETIRADO' AND registro_id IN (sid2::text,reg2::text,cambio::text) AND valor_anterior->>'activo'='true' AND valor_nuevo->>'activo'='false')<>3 THEN RAISE EXCEPTION 'Retiro sin auditoría'; END IF;
 den:=false; BEGIN PERFORM public.tend_guardar_semana(reg,datos||jsonb_build_object('semana_inicio','2026-10-19'),'Intento'); EXCEPTION WHEN raise_exception THEN IF SQLERRM='Semana retirada: solo consulta del historial' THEN den:=true; ELSE RAISE; END IF; END;
 IF NOT den THEN RAISE EXCEPTION 'Semana retirada reactivada'; END IF;
 INSERT INTO public.tend_cambios_filtro(org_id,instrumento_id,fecha,nota) VALUES(org,ins,'2026-10-26','QA activo') RETURNING id INTO cambio;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',operador,'role','authenticated')::text,true);
 INSERT INTO public.tend_extracciones(org_id,registro_id,foto_path,modulo,solicitado_por) VALUES(org,reg,org::text||'/qa.png','presiones',operador) RETURNING id INTO ex;
 INSERT INTO public.tend_registros_at(org_id,sistema,periodo_desde,periodo_hasta,instrumentos) VALUES(org,'T3c QA','2026-10-01','2026-10-31',jsonb_build_array(jsonb_build_object('id',ins))) RETURNING id INTO atid;
 EXECUTE 'RESET ROLE'; EXECUTE 'SET LOCAL ROLE service_role'; PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 PERFORM public.tend_extraccion_resultado(ex,jsonb_build_object('lecturas',lecturas),'[{"clave":"qa","version":"1.0"}]','modelo-qa');
 EXECUTE 'RESET ROLE'; EXECUTE 'SET LOCAL ROLE authenticated';
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',rs,'role','authenticated')::text,true);
 UPDATE public.tend_registros_at SET estado='emitido' WHERE id=atid;
 IF EXISTS(SELECT 1 FROM public.tend_registros_at a CROSS JOIN LATERAL jsonb_array_elements(a.datos_snapshot->'registros') r WHERE a.id=atid AND (r->>'id'=reg2::text OR EXISTS(SELECT 1 FROM jsonb_array_elements(r->'semanas') s WHERE s->>'id'=sid2::text))) THEN RAISE EXCEPTION 'Snapshot incluye retirados'; END IF;
 IF EXISTS(SELECT 1 FROM public.tend_registros_at a CROSS JOIN LATERAL jsonb_array_elements(a.datos_snapshot->'cambios') c WHERE a.id=atid AND c->>'activo'='false') THEN RAISE EXCEPTION 'Snapshot incluye filtro retirado'; END IF;
 den:=false; BEGIN PERFORM public.tend_corregir_fecha_semana(sid,'2026-11-02','QA'); EXCEPTION WHEN raise_exception THEN IF SQLERRM='Semana incluida en AT emitido: cambio rechazado' THEN den:=true; ELSE RAISE; END IF; END; IF NOT den THEN RAISE EXCEPTION 'Fecha emitida editable'; END IF;
 den:=false; BEGIN PERFORM public.tend_guardar_semana(reg,datos||jsonb_build_object('semana_inicio','2026-10-26'),'QA'); EXCEPTION WHEN raise_exception THEN IF SQLERRM='Semana incluida en AT emitido: cambio rechazado' THEN den:=true; ELSE RAISE; END IF; END; IF NOT den THEN RAISE EXCEPTION 'Manual emitida editable'; END IF;
 den:=false; BEGIN PERFORM public.tend_confirmar_extraccion(ex,datos||jsonb_build_object('semana_inicio','2026-10-26'),'QA'); EXCEPTION WHEN raise_exception THEN IF SQLERRM='Semana incluida en AT emitido: cambio rechazado' THEN den:=true; ELSE RAISE; END IF; END; IF NOT den THEN RAISE EXCEPTION 'Extracción emitida editable'; END IF;
 den:=false; BEGIN PERFORM public.tend_retirar('semana',sid,'QA'); EXCEPTION WHEN raise_exception THEN IF SQLERRM IN ('Semana incluida en AT emitido: cambio rechazado','Incluido en AT emitido: retiro rechazado') THEN den:=true; ELSE RAISE; END IF; END; IF NOT den THEN RAISE EXCEPTION 'Semana emitida retirable'; END IF;
 den:=false; BEGIN PERFORM public.tend_retirar('registro',reg,'QA'); EXCEPTION WHEN raise_exception THEN IF SQLERRM='Incluido en AT emitido: retiro rechazado' THEN den:=true; ELSE RAISE; END IF; END; IF NOT den THEN RAISE EXCEPTION 'Registro emitido retirable'; END IF;
 den:=false; BEGIN PERFORM public.tend_retirar('cambio_filtro',cambio,'QA'); EXCEPTION WHEN raise_exception THEN IF SQLERRM='Incluido en AT emitido: retiro rechazado' THEN den:=true; ELSE RAISE; END IF; END; IF NOT den THEN RAISE EXCEPTION 'Filtro emitido retirable'; END IF;
 EXECUTE 'RESET ROLE';
END $$;
SELECT 'T3c-1: motivo/fecha/colisiones/retiros/auditoría/snapshot/emitido manual-IA-retiro: PASA' AS resultado;
ROLLBACK;